export function nutria(mood, size = "", prop = null) {
  const m = MOODS[mood] || MOODS.free;
  const el = document.createElement("span");
  el.className = `nutria ${mood} ${size}`.trim();
  el.setAttribute("aria-hidden", "true");
  const extra = prop || m.prop;
  if (extra) el.dataset.prop = extra;
  const head = extra && HEAD_PROPS.has(extra) ? PROPS[extra] : "";
  const held = extra && !HEAD_PROPS.has(extra) ? PROPS[extra] : "";
  el.innerHTML = `<i class="ki"></i><svg viewBox="0 -1 17 15" shape-rendering="crispEdges"><g class="o-aura">${AURA}</g><g class="o-all"><g class="o-tail">${LAYERS.tail}</g><g class="o-torso">${LAYERS.body}</g>${LAYERS.feet}<g class="o-neck"><g class="o-head">${LAYERS.head}<g class="o-eyes"><g class="o-blink">${EYES[m.eyes]}</g></g><g class="o-hat"></g><g class="o-spikes">${SPIKES}</g>${head}</g></g><g class="o-torso"><g class="wear">${OUTFITS.scarf}</g>${ARMS[m.arms]}</g>${held}</g></svg>${m.bubble ? `<b class="bubble ${m.bubble[1]}">${m.bubble[0]}</b>` : ""}${m.zz ? '<i class="zz">z<span>z</span></i>' : ""}`;
  return el;
}

export const CLAYS = ["#d97757", "#e0a63b", "#5fa86b", "#4f9bd6", "#9b7fd6", "#d76f9c", "#3fb3a8", "#c4825a"];
const FURS = ["#8a5a3b", "#a0694a", "#6f4a33", "#b07d56", "#7d5a44", "#94704f"];
const hashOf = (name, mul, seed) => [...String(name || "")].reduce((n, ch) => (n * mul + ch.charCodeAt(0)) >>> 0, seed);

const OUTFIT_KEYS = Object.keys(OUTFITS);
const HAT_KEYS = ["none", "none", ...Object.keys(HATS).filter((k) => k !== "none")];

export function paint(el, name) {
  const clay = hashOf(name, 31, 7) % CLAYS.length;
  el.style.setProperty("--clay", CLAYS[clay]);
  el.style.setProperty("--hat", CLAYS[(clay + 3 + (hashOf(name, 13, 5) % 4)) % CLAYS.length]);
  el.style.setProperty("--fur", FURS[hashOf(name, 17, 3) % FURS.length]);
  el.style.setProperty("--nd", `-${(hashOf(name, 41, 13) % 4000) / 1000}s`);
  const wear = el.querySelector(".wear");
  const outfit = OUTFIT_KEYS[hashOf(name, 23, 19) % OUTFIT_KEYS.length];
  el.dataset.outfit = outfit;
  if (wear) wear.innerHTML = OUTFITS[outfit];
  const hat = el.querySelector(".o-hat");
  if (hat && !["helmet", "binoculars"].includes(el.dataset.prop)) hat.innerHTML = HATS[HAT_KEYS[hashOf(name, 37, 11) % HAT_KEYS.length]];
  return el;
}

const DOT_MOOD = { busy: "working", wait: "blocked", bad: "blocked", on: "idle", off: "free", "": "free" };

export function sessionNutria(name, dot, size = "avatar") {
  return paint(nutria(DOT_MOOD[dot] || "idle", size), name);
}
